<!doctype html><html lang="en"><meta charset="utf-8"><title>{{ $order->reference }}</title><style>body{font:15px Arial;margin:30px;color:#111}table{border-collapse:collapse;width:100%}th,td{padding:10px;border-bottom:1px solid #ccc;text-align:left}button{padding:12px}@media print{button{display:none}tr{break-inside:avoid}}</style><body><button onclick="window.print()">Print supplier copy</button><h1>{{ \App\Support\StoreSettings::brandName() }} / Purchase order</h1><h2>{{ $order->reference }} @if(!$order->issued_at) (DRAFT) @endif</h2><p>Supplier: {{ $order->supplier_name }}<br>Expected: {{ $order->expected_at?->format('d M Y') ?? 'To be agreed' }}<br>Supplier reference: {{ $order->supplier_reference ?? '?' }}</p><table><thead><tr><th>Item / store SKU / supplier SKU</th><th>Color / size</th><th>Units</th><th>Unit cost (PKR)</th><th>Line total (PKR)</th></tr></thead><tbody>@foreach($order->lines as $line)<tr><td>{{ $line->product_name }}<br>{{ $line->sku }} / {{ $line->supplier_sku ?? '?' }}</td><td>{{ $line->color }} / {{ $line->size }}</td><td>{{ $line->quantity }}</td><td>{{ $line->unit_cost_minor === null ? 'Not set' : \App\Services\Pricing::format($line->unit_cost_minor,'PKR') }}</td><td>{{ $line->unit_cost_minor === null ? 'Not set' : \App\Services\Pricing::format($line->quantity*$line->unit_cost_minor,'PKR') }}</td></tr>@endforeach</tbody></table><p>Total units: {{ $order->lines->sum('quantity') }}</p><p>Merchandise: {{ $order->lines->contains(fn($l)=>$l->unit_cost_minor===null) ? 'Incomplete ? costs missing' : \App\Services\Pricing::format($order->lines->sum(fn($l)=>$l->quantity*$l->unit_cost_minor),'PKR') }}</p><p>Freight estimate (separate): {{ $order->freight_minor===null ? 'Not set' : \App\Services\Pricing::format($order->freight_minor,'PKR') }}</p></body></html>